const items = $input.all();
const output = [];

/**
 * Convierte cualquier valor a string limpio.
 */
function toText(value) {
  if (value === null || value === undefined) {
    return '';
  }

  if (typeof value === 'string') {
    return value.trim();
  }

  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value).trim();
  }

  return '';
}


/**
 * Busca una cabecera de email dentro de distintas
 * estructuras posibles devueltas por Gmail/n8n.
 *
 * Ejemplo:
 * getHeaderValue(json, 'From')
 */
function getHeaderValue(json, headerName) {
  const target = String(headerName).toLowerCase();

  const possibleArrays = [
    json?.payload?.headers,
    json?.message?.payload?.headers,
    json?.data?.payload?.headers,
    json?.headers,
  ];

  // Headers como array:
  // [
  //   { name: "From", value: "Juan <juan@email.com>" }
  // ]
  for (const headers of possibleArrays) {
    if (!Array.isArray(headers)) {
      continue;
    }

    const found = headers.find(
      (header) =>
        String(header?.name || '').toLowerCase() === target
    );

    if (found?.value) {
      return found.value;
    }
  }

  // Headers como objeto:
  // {
  //   from: "...",
  //   subject: "..."
  // }
  const possibleObjects = [
    json?.headers,
    json?.payload?.headers,
  ];

  for (const headers of possibleObjects) {
    if (
      !headers ||
      typeof headers !== 'object' ||
      Array.isArray(headers)
    ) {
      continue;
    }

    const key = Object.keys(headers).find(
      (k) => String(k).toLowerCase() === target
    );

    if (key) {
      return headers[key];
    }
  }

  return '';
}


/**
 * Extrae una dirección email de múltiples formatos.
 *
 * Soporta:
 * "Juan Perez <juan@empresa.com>"
 * "juan@empresa.com"
 * { email: "juan@empresa.com" }
 * { address: "juan@empresa.com" }
 * arrays
 */
function extractEmail(value) {
  if (!value) {
    return '';
  }

  if (typeof value === 'string') {
    const match = value.match(
      /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i
    );

    return match
      ? match[0].trim().toLowerCase()
      : '';
  }

  if (Array.isArray(value)) {
    for (const element of value) {
      const email = extractEmail(element);

      if (email) {
        return email;
      }
    }

    return '';
  }

  if (typeof value === 'object') {
    const candidates = [
      value.email,
      value.address,
      value.value,
      value.text,
      value.from,
      value.sender,
    ];

    for (const candidate of candidates) {
      const email = extractEmail(candidate);

      if (email) {
        return email;
      }
    }
  }

  return '';
}


/**
 * Determina el remitente usando diferentes
 * estructuras posibles del Gmail Trigger.
 */
function getSenderEmail(json) {
  const candidates = [
    json?.senderEmail,
    json?.from,
    json?.From,
    json?.sender,
    json?.Sender,
    json?.replyTo,
    json?.reply_to,
    json?.message?.from,
    json?.data?.from,

    getHeaderValue(json, 'From'),
    getHeaderValue(json, 'Reply-To'),
    getHeaderValue(json, 'Sender'),
  ];

  for (const candidate of candidates) {
    const email = extractEmail(candidate);

    if (email) {
      return email;
    }
  }

  return '';
}


/**
 * Obtiene el asunto del correo.
 */
function getSubject(json) {
  const candidates = [
    json?.subject,
    json?.Subject,
    json?.message?.subject,
    json?.data?.subject,
    getHeaderValue(json, 'Subject'),
  ];

  for (const candidate of candidates) {
    const text = toText(candidate);

    if (text) {
      return text;
    }
  }

  return '';
}


/**
 * Obtiene el ID del mensaje Gmail.
 */
function getMessageId(json) {
  return (
    toText(json?.id) ||
    toText(json?.messageId) ||
    toText(json?.message_id) ||
    toText(json?.message?.id) ||
    ''
  );
}


/**
 * Obtiene threadId de Gmail.
 */
function getThreadId(json) {
  return (
    toText(json?.threadId) ||
    toText(json?.thread_id) ||
    toText(json?.message?.threadId) ||
    ''
  );
}


/**
 * Obtiene extensión limpia.
 */
function getFileExtension(file) {
  const explicitExtension = toText(
    file?.fileExtension
  )
    .replace(/^\./, '')
    .toLowerCase();

  if (explicitExtension) {
    return explicitExtension;
  }

  const fileName = toText(file?.fileName);

  if (!fileName.includes('.')) {
    return '';
  }

  return fileName
    .split('.')
    .pop()
    .replace(/^\./, '')
    .toLowerCase();
}


/**
 * Clasifica el archivo.
 */
function detectFileType(file) {
  const extension = getFileExtension(file);

  const mimeType = toText(
    file?.mimeType
  ).toLowerCase();

  // PDF
  if (
    extension === 'pdf' ||
    mimeType === 'application/pdf'
  ) {
    return {
      fileType: 'PDF',
      extension,
      mimeType,
      supported: true,
    };
  }

  // XML
  if (
    extension === 'xml' ||
    mimeType === 'application/xml' ||
    mimeType === 'text/xml' ||
    mimeType.includes('xml')
  ) {
    return {
      fileType: 'XML',
      extension,
      mimeType,
      supported: true,
    };
  }

  // Imágenes admitidas
  const imageExtensions = [
    'jpg',
    'jpeg',
    'png',
    'webp',
    'tif',
    'tiff',
  ];

  if (
    imageExtensions.includes(extension) ||
    mimeType.startsWith('image/')
  ) {
    return {
      fileType: 'IMAGE',
      extension,
      mimeType,
      supported: true,
    };
  }

  // Otros
  return {
    fileType: 'UNSUPPORTED',
    extension,
    mimeType,
    supported: false,
  };
}


/**
 * Detecta si probablemente se trata de una imagen
 * inline pequeña de firma/logo.
 *
 * Por ahora NO la descartamos automáticamente.
 * Solo dejamos el flag para usarlo después.
 */
function detectPossibleInlineImage(file) {
  const mimeType = toText(
    file?.mimeType
  ).toLowerCase();

  const fileName = toText(
    file?.fileName
  ).toLowerCase();

  if (!mimeType.startsWith('image/')) {
    return false;
  }

  const suspiciousNames = [
    'logo',
    'signature',
    'firma',
    'icon',
    'image00',
    'image01',
  ];

  return suspiciousNames.some(
    (name) => fileName.includes(name)
  );
}


/**
 * Procesamiento principal
 */
for (const item of items) {
  const json = item.json || {};
  const binaries = item.binary || {};

  const senderEmail = getSenderEmail(json);
  const subject = getSubject(json);

  const gmailMessageId = getMessageId(json);
  const threadId = getThreadId(json);

  const binaryKeys = Object.keys(binaries);

  /**
   * Caso defensivo:
   * correo sin adjuntos.
   */
  if (binaryKeys.length === 0) {
    output.push({
      json: {
        gmailMessageId,
        threadId,

        senderEmail,
        subject,

        fileName: null,
        fileExtension: null,
        mimeType: null,

        fileType: 'NO_ATTACHMENT',
        supported: false,

        sourceBinaryKey: null,
        binaryProperty: null,

        possibleInlineImage: false,

        processingStatus: 'NO_ATTACHMENT',

        errorReason:
          'El correo no contiene archivos binarios descargados',

        processedAt:
          new Date().toISOString(),
      },
    });

    continue;
  }

  /**
   * Creamos un item independiente por adjunto.
   */
  for (const binaryKey of binaryKeys) {
    const file = binaries[binaryKey];

    if (!file) {
      continue;
    }

    const {
      fileType,
      extension,
      mimeType,
      supported,
    } = detectFileType(file);

    const possibleInlineImage =
      detectPossibleInlineImage(file);

    output.push({
      json: {
        // Gmail
        gmailMessageId,
        threadId,
        senderEmail,
        subject,

        // Archivo
        fileName:
          toText(file?.fileName) || null,

        fileExtension:
          extension || null,

        mimeType:
          mimeType || null,

        fileType,
        supported,

        // Trazabilidad del binario
        sourceBinaryKey: binaryKey,

        // A partir de aquí todos los nodos
        // utilizarán siempre binary.data
        binaryProperty: 'data',

        possibleInlineImage,

        processingStatus:
          supported
            ? 'READY'
            : 'UNSUPPORTED',

        processedAt:
          new Date().toISOString(),
      },

      /**
       * Normalizamos:
       *
       * attachment_0
       * attachment_1
       * ...
       *
       * a:
       *
       * binary.data
       */
      binary: {
        data: file,
      },
    });
  }
}

return output;

// ============================================================
// P04.1 PDF - RESTAURAR CONTEXTO DEL CORREO
// ============================================================

const extracted = $json ?? {};

// Recuperamos el item original que salió de P03
const sourceItem =
  $('Enrutar por tipo de archivo (P03)').item;

const source =
  sourceItem.json ?? {};

// El Extract From PDF normalmente devuelve el texto
// en "text". Dejamos alternativas por seguridad.
const extractedText =
  extracted.text ??
  extracted.rawText ??
  extracted.content ??
  '';


return {
  json: {
    // Recuperamos Gmail + archivo + fileType
    ...source,

    // Dejamos claro que viene de PDF
    sourceType: 'PDF',
    extractionProvider: 'pdf',

    // Texto extraído
    rawText: extractedText,
  },

  // Conservamos el PDF
  binary:
    sourceItem.binary,
};

// ============================================================
// P04.2 PDF - EXTRAER CAMPOS DESDE TEXTO DE PDF
// ============================================================
//
// V1:
// Parser determinista para facturas PDF digitales.
// No usa Vision.
// No usa IA.
//
// Conserva:
// - metadata Gmail
// - archivo binario
// - rawText
//
// Produce los mismos campos que la rama IMAGE.
// ============================================================

const item = $input.item;
const j = item.json ?? {};

const rawText =
  String(
    j.rawText ??
    j.text ??
    j.content ??
    ''
  ).trim();


// ============================================================
// VALIDACIÓN
// ============================================================

if (!rawText) {
  return {
    json: {
      ...j,

      sourceType: 'PDF',
      extractionProvider: 'pdf-text',

      documentType: 'invoice',
      isFinancialDocument: false,

      supplierName: null,
      supplierTaxId: null,
      documentNumber: null,
      issueDate: null,
      currency: null,

      subtotal: null,
      tax: null,
      total: null,

      rawText,

      confidence: 0,

      pdfExtractionOk: false,
      pdfExtractionError: 'PDF_WITHOUT_EXTRACTABLE_TEXT',
    },

    binary: item.binary,
  };
}


// ============================================================
// HELPERS
// ============================================================

function firstMatch(text, patterns) {

  for (const regex of patterns) {

    const match =
      text.match(regex);

    if (
      match &&
      match[1] !== undefined
    ) {
      return String(match[1]).trim();
    }
  }

  return null;
}


function amount(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  let text =
    String(value)
      .trim()
      .replace(/\s/g, '')
      .replace(/[^\d,.\-]/g, '');

  if (!text) {
    return null;
  }

  const comma =
    text.lastIndexOf(',');

  const dot =
    text.lastIndexOf('.');

  // 1.234,56
  if (comma > dot) {

    text =
      text
        .replace(/\./g, '')
        .replace(',', '.');
  }

  // 1,234.56
  else if (
    dot > comma &&
    comma !== -1
  ) {

    text =
      text.replace(/,/g, '');
  }

  // 17,70
  else if (
    comma !== -1 &&
    dot === -1
  ) {

    text =
      text.replace(',', '.');
  }

  const number =
    Number(text);

  return Number.isFinite(number)
    ? number
    : null;
}


function isoDate(value) {

  if (!value) {
    return null;
  }

  const text =
    String(value).trim();

  // DD/MM/YYYY
  let match =
    text.match(
      /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/
    );

  if (match) {

    const day =
      match[1].padStart(2, '0');

    const month =
      match[2].padStart(2, '0');

    return `${match[3]}-${month}-${day}`;
  }

  // YYYY-MM-DD
  match =
    text.match(
      /^(\d{4})-(\d{2})-(\d{2})$/
    );

  if (match) {
    return text;
  }

  return null;
}


// ============================================================
// 1. RUC DEL EMISOR
// ============================================================
//
// Tomamos la PRIMERA aparición de RUC.
// Normalmente corresponde al proveedor/emisor.
// ============================================================

const supplierTaxId =
  firstMatch(
    rawText,
    [
      /R\.?\s*U\.?\s*C\.?\s*(?:N[°º.]*)?\s*[:\-]?\s*(\d{11})/i,
      /\bRUC\s*[:\-]?\s*(\d{11})/i,
    ]
  );


// ============================================================
// 2. NÚMERO DE COMPROBANTE
// ============================================================
//
// Ejemplos:
// F001-31663
// E001-2842
// B001-123456
// ============================================================

const documentNumberRaw =
  firstMatch(
    rawText,
    [
      /(?:FACTURA|BOLETA)[\s\S]{0,150}?\b([FBE]\d{3}\s*-\s*\d{1,12})\b/i,
      /\b([FBE]\d{3}\s*-\s*\d{1,12})\b/i,
    ]
  );

const documentNumber =
  documentNumberRaw
    ? documentNumberRaw
        .toUpperCase()
        .replace(/\s+/g, '')
    : null;


// ============================================================
// 3. FECHA DE EMISIÓN
// ============================================================

const issueDateRaw =
  firstMatch(
    rawText,
    [
      /Fecha\s+(?:de\s+)?Emisi[oó]n\s*[:\-]?\s*(\d{1,2}\/\d{1,2}\/\d{4})/i,
      /Fecha\s+(?:de\s+)?Emisi[oó]n\s*[:\-]?\s*(\d{4}-\d{2}-\d{2})/i,
    ]
  );

const issueDate =
  isoDate(issueDateRaw);


// ============================================================
// 4. MONEDA
// ============================================================

let currency = null;

if (
  /\bSOLES?\b/i.test(rawText) ||
  /\bPEN\b/i.test(rawText) ||
  /S\/\s*\d/i.test(rawText)
) {

  currency = 'PEN';
}

else if (
  /\bD[ÓO]LARES?\b/i.test(rawText) ||
  /\bUSD\b/i.test(rawText) ||
  /\$\s*\d/i.test(rawText)
) {

  currency = 'USD';
}


// ============================================================
// 5. SUBTOTAL
// ============================================================

const subtotal =
  amount(
    firstMatch(
      rawText,
      [
        /Sub\s*Total\s*(?:Ventas?)?\s*[:\-]?\s*(?:S\/\.?|USD|\$)?\s*([\d.,]+)/i,
        /Valor\s+Venta\s*[:\-]?\s*(?:S\/\.?|USD|\$)?\s*([\d.,]+)/i,
        /Subtotal\s*[:\-]?\s*(?:S\/\.?|USD|\$)?\s*([\d.,]+)/i,
      ]
    )
  );


// ============================================================
// 6. IGV / IMPUESTO
// ============================================================

const tax =
  amount(
    firstMatch(
      rawText,
      [
        /\bIGV\s*[:\-]?\s*(?:S\/\.?|USD|\$)?\s*([\d.,]+)/i,
        /\bIVA\s*[:\-]?\s*(?:S\/\.?|USD|\$)?\s*([\d.,]+)/i,
        /\bImpuesto\s*[:\-]?\s*(?:S\/\.?|USD|\$)?\s*([\d.,]+)/i,
      ]
    )
  );


// ============================================================
// 7. TOTAL
// ============================================================

const total =
  amount(
    firstMatch(
      rawText,
      [
        /Importe\s+Total\s*[:\-]?\s*(?:S\/\.?|USD|\$)?\s*([\d.,]+)/i,
        /Total\s+(?:a\s+Pagar|Venta)\s*[:\-]?\s*(?:S\/\.?|USD|\$)?\s*([\d.,]+)/i,
        /\bTOTAL\s*[:\-]?\s*(?:S\/\.?|USD|\$)?\s*([\d.,]+)/i,
      ]
    )
  );


// ============================================================
// 8. NOMBRE DEL PROVEEDOR
// ============================================================
//
// Buscamos una razón social cerca del inicio del documento,
// antes de los datos del cliente.
// ============================================================

const header =
  rawText.slice(
    0,
    Math.min(
      rawText.length,
      1800
    )
  );

const lines =
  header
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean);


const corporateRegex =
  /\b(S\.?A\.?C\.?|S\.?A\.?|E\.?I\.?R\.?L\.?|S\.?R\.?L\.?|SAC|EIRL|SRL)\b/i;

let supplierName = null;

for (const line of lines) {

  if (
    corporateRegex.test(line) &&
    !/SEÑOR|CLIENTE|ADQUIRIENTE/i.test(line)
  ) {

    supplierName = line;
    break;
  }
}


// ============================================================
// 9. TIPO DE DOCUMENTO
// ============================================================

let documentType = 'invoice';

if (/BOLETA/i.test(rawText)) {
  documentType = 'receipt';
}

else if (/TICKET/i.test(rawText)) {
  documentType = 'ticket';
}


// ============================================================
// 10. CONFIANZA HEURÍSTICA
// ============================================================

const importantFields = [
  supplierTaxId,
  documentNumber,
  issueDate,
  subtotal,
  tax,
  total,
];

const foundFields =
  importantFields.filter(
    value =>
      value !== null &&
      value !== undefined &&
      value !== ''
  ).length;

const confidence =
  Number(
    (
      foundFields /
      importantFields.length
    ).toFixed(2)
  );


// ============================================================
// 11. VALIDACIÓN DE EXTRACCIÓN
// ============================================================

const pdfExtractionOk =
  Boolean(
    supplierTaxId &&
    documentNumber &&
    issueDate &&
    total !== null &&
    total > 0
  );


// ============================================================
// SALIDA
// ============================================================

return {
  json: {

    // Mantener Gmail + archivo + metadata
    ...j,

    sourceType: 'PDF',
    extractionProvider: 'pdf-text-parser',

    documentType,
    isFinancialDocument:
      pdfExtractionOk,

    supplierName,
    supplierTaxId,
    documentNumber,
    issueDate,
    currency,

    subtotal,
    tax,
    total,

    rawText,

    confidence,

    pdfExtractionOk,

    pdfExtractedAt:
      new Date().toISOString(),
  },

  binary:
    item.binary,
};

// ============================================================
// P04.1 - Parsear OpenAI Vision
// ============================================================

const aiResponse = $json;

// Recuperamos el item original proveniente de P03.
// Así conservamos metadata + binary.data.
const sourceItem = $('Enrutar por tipo de archivo (P03)').item;


// ============================================================
// CONFIGURACIÓN
// ============================================================

const CONFIDENCE_THRESHOLD = 0.70;


// ============================================================
// HELPERS
// ============================================================

function cleanJsonString(value) {
  return String(value)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}


function looksLikeInvoicePayload(obj) {
  if (
    !obj ||
    typeof obj !== 'object' ||
    Array.isArray(obj)
  ) {
    return false;
  }

  return (
    'documentType' in obj ||
    'isFinancialDocument' in obj ||
    'supplierName' in obj ||
    'supplierTaxId' in obj ||
    'documentNumber' in obj ||
    'total' in obj
  );
}


/**
 * Busca recursivamente un JSON válido dentro de la
 * respuesta de OpenAI/n8n.
 *
 * Funciona si:
 * - viene como objeto
 * - viene en content[].text
 * - viene como output_text
 * - viene como string JSON
 */
function findStructuredPayload(value) {
  if (value === null || value === undefined) {
    return null;
  }

  // Ya es objeto estructurado
  if (
    typeof value === 'object' &&
    !Array.isArray(value) &&
    looksLikeInvoicePayload(value)
  ) {
    return value;
  }

  // String potencialmente JSON
  if (typeof value === 'string') {
    const cleaned = cleanJsonString(value);

    if (
      cleaned.startsWith('{') &&
      cleaned.endsWith('}')
    ) {
      try {
        const parsed = JSON.parse(cleaned);

        if (looksLikeInvoicePayload(parsed)) {
          return parsed;
        }
      } catch {
        // Continuamos buscando
      }
    }

    return null;
  }

  // Array
  if (Array.isArray(value)) {
    for (const child of value) {
      const found = findStructuredPayload(child);

      if (found) {
        return found;
      }
    }

    return null;
  }

  // Objeto genérico
  if (typeof value === 'object') {

    // Caso OpenAI típico:
    // {
    //   type: "output_text",
    //   text: "{...}"
    // }
    if (
      value.type === 'output_text' &&
      typeof value.text === 'string'
    ) {
      const found = findStructuredPayload(value.text);

      if (found) {
        return found;
      }
    }

    // Buscar recursivamente
    for (const child of Object.values(value)) {
      const found = findStructuredPayload(child);

      if (found) {
        return found;
      }
    }
  }

  return null;
}


/**
 * Número nullable.
 */
function toNullableNumber(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  if (typeof value === 'number') {
    return Number.isFinite(value)
      ? value
      : null;
  }

  let text = String(value)
    .trim()
    .replace(/\s/g, '')
    .replace(/[^\d,.\-]/g, '');

  if (!text) {
    return null;
  }

  const comma = text.lastIndexOf(',');
  const dot = text.lastIndexOf('.');

  // 1.234,56
  if (comma > dot) {
    text = text
      .replace(/\./g, '')
      .replace(',', '.');
  }

  // 1,234.56
  else if (
    dot > comma &&
    comma !== -1
  ) {
    text = text.replace(/,/g, '');
  }

  // 18,50
  else if (
    comma !== -1 &&
    dot === -1
  ) {
    text = text.replace(',', '.');
  }

  const number = Number(text);

  return Number.isFinite(number)
    ? number
    : null;
}


/**
 * Normaliza confidence.
 *
 * Acepta:
 * 0.9
 * "0.9"
 * 90  -> 0.90
 */
function normalizeConfidence(value) {
  let confidence = Number(value ?? 0);

  if (!Number.isFinite(confidence)) {
    return 0;
  }

  // Si el modelo accidentalmente devuelve 90 en vez de 0.90
  if (
    confidence > 1 &&
    confidence <= 100
  ) {
    confidence = confidence / 100;
  }

  return Math.min(
    1,
    Math.max(0, confidence)
  );
}


// ============================================================
