function cleanJsonString(value) {
  return String(value)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}


function looksLikeInvoicePayload(obj) {
  if (
    !obj ||
    typeof obj !== 'object' ||
    Array.isArray(obj)
  ) {
    return false;
  }

  return (
    'documentType' in obj ||
    'isFinancialDocument' in obj ||
    'supplierName' in obj ||
    'supplierTaxId' in obj ||
    'documentNumber' in obj ||
    'total' in obj
