/**
 * Busca el JSON de Gemini sin depender de una
 * ruta exacta.
 *
 * Soporta:
 * - objetos
 * - strings JSON
 * - content
 * - text
 * - parts[]
 * - candidates[]
 * - respuestas simplificadas por n8n
 */
function findStructuredPayload(value) {
  if (value === null || value === undefined) {
    return null;
  }

  // Ya está parseado
  if (
    typeof value === 'object' &&
    !Array.isArray(value) &&
    looksLikeInvoicePayload(value)
  ) {
    return value;
  }

  // String JSON
  if (typeof value === 'string') {
    const cleaned = cleanJsonString(value);

    if (
      cleaned.startsWith('{') &&
      cleaned.endsWith('}')
    ) {
      try {
        const parsed = JSON.parse(cleaned);

        if (looksLikeInvoicePayload(parsed)) {
          return parsed;
        }
      } catch {
        // continuar
      }
    }

    return null;
  }

  // Arrays
  if (Array.isArray(value)) {
    for (const child of value) {
      const found = findStructuredPayload(child);

      if (found) {
        return found;
      }
    }

    return null;
  }

  // Objetos genéricos
  if (typeof value === 'object') {
    for (const child of Object.values(value)) {
      const found = findStructuredPayload(child);

      if (found) {
        return found;
      }
    }
  }

  return null;
}


function toNullableNumber(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  if (typeof value === 'number') {
    return Number.isFinite(value)
      ? value
      : null;
  }

  let text = String(value)
    .trim()
    .replace(/\s/g, '')
    .replace(/[^\d,.\-]/g, '');

  if (!text) {
    return null;
  }

  const comma = text.lastIndexOf(',');
  const dot = text.lastIndexOf('.');

  // 1.234,56
  if (comma > dot) {
    text = text
      .replace(/\./g, '')
      .replace(',', '.');
  }

  // 1,234.56
  else if (
    dot > comma &&
    comma !== -1
  ) {
    text = text.replace(/,/g, '');
  }

  // 18,50
  else if (
    comma !== -1 &&
    dot === -1
  ) {
    text = text.replace(',', '.');
  }

  const number = Number(text);

  return Number.isFinite(number)
    ? number
    : null;
}


