  else if (!isValidISODate(issueDate)) {
    errors.push(
      'INVALID_ISSUE_DATE'
    );
  }

  else if (
    isFutureDate(
      issueDate,
      POLICY.maxFutureDays
    )
  ) {
    errors.push(
      'FUTURE_ISSUE_DATE'
    );
  }
}


// ------------------------------------------------------------
// Moneda
// ------------------------------------------------------------

if (!currency) {

  if (POLICY.requireCurrency) {
    errors.push(
      'MISSING_CURRENCY'
    );
  }

  else {
    warnings.push(
      'MISSING_CURRENCY'
    );
  }
}


// ------------------------------------------------------------
// Total
// ------------------------------------------------------------

if (total === null) {
  errors.push(
    'MISSING_TOTAL'
  );
}

else if (total <= 0) {
  errors.push(
    'INVALID_TOTAL'
  );
}


// ============================================================
// CONSISTENCIA ARITMÉTICA
// ============================================================

let totalsConsistent = null;
let totalsDifference = null;

if (
  subtotal !== null &&
  tax !== null &&
  total !== null
) {

  totalsDifference =
    Math.abs(
      subtotal + tax - total
    );

  totalsConsistent =
    totalsDifference <=
    POLICY.totalsTolerance;


  if (
    POLICY.requireConsistentTotals &&
    !totalsConsistent
  ) {
    errors.push(
      'TOTALS_NOT_CONSISTENT'
    );
  }
}

else {
  // No rechazamos automáticamente si faltan
  // subtotal/impuesto pero sí existe total.
  warnings.push(
    'TOTAL_COMPONENTS_INCOMPLETE'
  );
}


// ============================================================
// DUPLICATE KEY PARA P07
// ============================================================

if (!duplicateKey) {
  errors.push(
    'MISSING_DUPLICATE_KEY'
  );
}


// ============================================================
// ESTADO FINAL
// ============================================================

const invoiceValid =
  errors.length === 0;

const invoiceValidationStatus =
  invoiceValid
    ? 'VALID'
    : 'INVALID';


// ============================================================
// SALIDA
// ============================================================

return {
  json: {
    ...j,

    // P06
    invoiceValid,
    invoiceValidationStatus,

    invoiceValidationErrors:
      errors,

    invoiceValidationWarnings:
      warnings,

    // Recalculamos para no depender
    // únicamente del normalizador.
    totalsConsistent,
    totalsDifference,

    invoiceValidatedAt:
      new Date().toISOString()
  },

  // Conservamos archivo original
  binary: item.binary
};

// ============================================================
// P07.1 - PREPARAR RESULTADO DE DUPLICIDAD
// ============================================================

const sourceItem =
  $('Evaluar factura (P08.2)').first();

if (!sourceItem) {
  throw new Error(
    'No se encontró el item de Evaluar factura (P06.1)'
  );
}

const invoice = sourceItem.json ?? {};
const sheetRow = $json ?? {};


// ============================================================
// HELPERS
// ============================================================

function normalizeKey(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  return String(value)
    .trim()
    .replace(/\s+/g, '')
    .toUpperCase();
}


// ============================================================
// CLAVES
// ============================================================

const searchedDuplicateKey =
  normalizeKey(
    invoice.duplicateKey
  );

const foundDuplicateKey =
  normalizeKey(
    sheetRow.duplicateKey ??
    sheetRow.DuplicateKey ??
    sheetRow.duplicate_key
  );


// ============================================================
// DUPLICIDAD
// ============================================================

const duplicateFound =
  Boolean(
    searchedDuplicateKey &&
    foundDuplicateKey &&
    searchedDuplicateKey === foundDuplicateKey
  );


// ============================================================
// SALIDA
// ============================================================

return {
  json: {
    ...invoice,

    duplicateChecked: true,

    duplicateFound,

    duplicateStatus:
      duplicateFound
        ? 'DUPLICATE'
        : 'UNIQUE',

    searchedDuplicateKey,

    matchedDuplicateKey:
      duplicateFound
        ? foundDuplicateKey
        : null,

    duplicateRowNumber:
      duplicateFound
        ? (
            sheetRow.row_number ??
            null
          )
        : null,

    duplicateCheckedAt:
      new Date().toISOString(),
  },

  binary:
    sourceItem.binary,
};

