parameters.jsCode:
// ============================================================
// P07.3 - PARSEAR DECISIÓN DEL AI AGENT
// Versión consolidada y mejorada
// ============================================================
//
// Responsabilidades:
//
// 1. Recuperar la factura original.
// 2. Parsear el JSON textual devuelto por AI Agent.
// 3. Validar categoría.
// 4. Normalizar confidence.
// 5. Normalizar datos obtenidos desde la Tool.
// 6. Detectar restricciones.
// 7. Determinar si requiere revisión humana.
// 8. Conservar binary.data.
// ============================================================


// ============================================================
// 1. RECUPERAR FACTURA ORIGINAL
// ============================================================
//
// IMPORTANTE:
//
// No usamos:
//
// $('¿Factura duplicada? (P15)').item
//
// porque AI Agent + Tools pueden romper el paired-item linking.
//
// Para este workflow actual procesamos una factura por ejecución,
// por lo que recuperamos directamente el primer item estable antes
// del IF de duplicados.
// ============================================================

const sourceItem =
  $('Preparar duplicado (P14)').first();

if (!sourceItem) {
  throw new Error(
    'No se encontró información en el nodo "Preparar duplicado (P07.1)"'
  );
}

const source =
  sourceItem.json ?? {};


// ============================================================
// 2. RESPUESTA DEL AI AGENT
// ============================================================
//
// En tu versión de n8n comprobamos que AI Agent devuelve:
// {
//   output: "{ ...JSON... }"
// }
// ============================================================

const raw =
  $json.output ??
  $json.text ??
  $json.response ??
  '';


// ============================================================
// 3. CONFIGURACIÓN
// ============================================================

const CONFIDENCE_THRESHOLD = 0.70;


// Categorías que pueden consultar política
const ACTIONABLE_CATEGORIES = new Set([
  'BREAKFAST',
  'LUNCH',
  'DINNER',
  'MOBILITY',
  'AIRFARE',
  'LODGING',
  'ALLOWED_BEVERAGES',
  'MINOR_PURCHASE',
]);


// Todas las categorías admitidas
const ALL_CATEGORIES = new Set([
  ...ACTIONABLE_CATEGORIES,
  'OTHER',
  'UNCERTAIN',
]);


// Labels controlados por n8n.
// No dependemos del texto escrito por la IA.
const CATEGORY_LABELS = {
  BREAKFAST: 'Desayuno',
  LUNCH: 'Almuerzo',
  DINNER: 'Cena',
  MOBILITY: 'Movilidad',
  AIRFARE: 'Pasaje aéreo',
  LODGING: 'Hospedaje',
  ALLOWED_BEVERAGES: 'Bebidas permitidas',
  MINOR_PURCHASE: 'Compra menor',
  OTHER: 'Otro',
  UNCERTAIN: 'No determinado',
};


// ============================================================
// 4. HELPERS
// ============================================================


/**
 * Limpia respuestas tipo:
 *
 * ```json
 * { ... }
 * ```
 */
function cleanJsonString(value) {

  return String(value ?? '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}


/**
 * Intenta interpretar la respuesta del Agent.
 *
 * Soporta:
 * - JSON puro
 * - ```json ... ```
 * - texto accidental alrededor del JSON
 */
function parseAgentJson(value) {

  const cleaned =
    cleanJsonString(value);

  if (!cleaned) {
    return null;
  }


  // ----------------------------
  // Intento 1: JSON puro
  // ----------------------------

  try {

    const parsed =
      JSON.parse(cleaned);

    if (
      parsed &&
      typeof parsed === 'object' &&
      !Array.isArray(parsed)
    ) {
      return parsed;
    }

  } catch {
    // Continuar al segundo intento
  }


  // ----------------------------
  // Intento 2:
  // extraer primer { ... último }
  // ----------------------------

  const start =
    cleaned.indexOf('{');

  const end =
    cleaned.lastIndexOf('}');


  if (
    start !== -1 &&
    end !== -1 &&
    end > start
  ) {

    const candidate =
      cleaned.slice(
        start,
        end + 1
      );

    try {

      const parsed =
        JSON.parse(candidate);

      if (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      ) {
        return parsed;
      }

    } catch {
      return null;
    }
  }

  return null;
}


/**
 * Convierte confidence a escala 0-1.
 *
 * Soporta:
 *
 * 0.95
 * "0.95"
 * 95 → 0.95
 */
function normalizeConfidence(value) {

  let number =
    Number(value ?? 0);

  if (!Number.isFinite(number)) {
    return 0;
  }


  // Por si el modelo devuelve 95
  // en vez de 0.95
  if (
    number > 1 &&
    number <= 100
  ) {
    number =
      number / 100;
  }


  // Clamp 0-1
  return Math.min(
    1,
    Math.max(
      0,
      number
    )
  );
}


/**
 * Convierte valores tipo:
 *
 * SI
 * NO
 * TRUE
 * FALSE
 * 1
 * 0
 *
 * a boolean/null.
 */
function normalizeBoolean(value) {

  if (value === true) {
    return true;
  }

  if (value === false) {
    return false;
  }


  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }


  const normalized =
    String(value)
      .trim()
      .toUpperCase();


  if (
    [
      'SI',
      'SÍ',
      'YES',
      'TRUE',
      '1'
    ].includes(normalized)
  ) {
    return true;
  }


  if (
    [
      'NO',
      'FALSE',
      '0'
    ].includes(normalized)
  ) {
    return false;
  }


  return null;
}


/**
 * Normaliza políticas que pueden contener:
 *
 * SI
 * NO
 * DEPENDE
 *
 * Retorna:
 *
 * YES
 * NO
 * CONDITIONAL
 * UNKNOWN
 */
function normalizeReviewStatus(value) {

  if (value === true) {
    return 'YES';
  }

  if (value === false) {
    return 'NO';
  }


  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return 'UNKNOWN';
  }


  const normalized =
    String(value)
      .trim()
      .toUpperCase();


  if (
    [
      'SI',
      'SÍ',
      'YES',
      'TRUE',
      '1'
    ].includes(normalized)
  ) {
    return 'YES';
  }


  if (
    [
      'NO',
      'FALSE',
      '0'
    ].includes(normalized)
  ) {
    return 'NO';
  }


  if (
    [
      'DEPENDE',
      'CONDITIONAL',
      'CONDICIONAL',
      'REVIEW'
    ].includes(normalized)
  ) {
    return 'CONDITIONAL';
  }


  return 'UNKNOWN';
}


/**
 * Convierte un importe a Number/null.
 *
 * Soporta:
 *
 * 40
 * "40"
 * "40.00"
 * "40,00"
 * "S/ 40.00"
 */
function nullableNumber(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }


  if (typeof value === 'number') {

    return Number.isFinite(value)
      ? value
      : null;
  }


  let text =
    String(value)
      .trim()
      .replace(/\s/g, '')
      .replace(/[^\d,.\-]/g, '');


  if (!text) {
    return null;
  }


  const lastComma =
    text.lastIndexOf(',');

  const lastDot =
    text.lastIndexOf('.');


  // 1.234,56
  if (
    lastComma > lastDot
  ) {

    text =
      text
        .replace(/\./g, '')
        .replace(',', '.');
  }

  // 1,234.56
  else if (
    lastDot > lastComma &&
    lastComma !== -1
  ) {

    text =
      text.replace(/,/g, '');
  }

  // 40,50
  else if (
    lastComma !== -1 &&
    lastDot === -1
  ) {

    text =
      text.replace(',', '.');
  }


  const number =
    Number(text);


  return Number.isFinite(number)
    ? number
    : null;
}


/**
 * Normaliza arrays de strings.
 */
function normalizeArray(value) {

  if (!Array.isArray(value)) {
    return [];
  }


  return value
    .map(
      item =>
        String(item ?? '').trim()
    )
    .filter(Boolean);
}


/**
 * Normaliza texto nullable.
 */
function normalizeText(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }


  const text =
    String(value).trim();


  return text || null;
}


// ============================================================
// 5. PARSEAR RESPUESTA
// ============================================================

const parsed =
  parseAgentJson(raw);


// ============================================================
// 6. ERROR DE PARSEO
// ============================================================

if (!parsed) {

  return {

    json: {

      // Conservamos todos los datos anteriores
      ...source,


      // --------------------------
      // Estado Agent
      // --------------------------

      agentResponseParsed: false,

      agentDecisionOk: false,

      policyContextReady: false,


      // --------------------------
      // Clasificación segura
      // --------------------------

      expenseCategory:
        'UNCERTAIN',

      expenseCategoryLabel:
        'No determinado',

      expenseConfidence:
        0,

      expenseConfidenceThreshold:
        CONFIDENCE_THRESHOLD,

      expenseMeetsConfidenceThreshold:
        false,

      expenseEvidence: [],

      classificationReason:
        'No se pudo interpretar la respuesta del AI Agent.',


      // --------------------------
      // Restricciones
      // --------------------------

      containsPotentiallyRestrictedItems:
        false,

      restrictedItems: [],


      // --------------------------
      // Tool / Política
      // --------------------------

      toolUsed:
        false,

      policyFound:
        false,

      policyAllowed:
        null,

      policyLimit:
        null,

      policyRequiresReviewStatus:
        'UNKNOWN',

      taxReviewStatus:
        'UNKNOWN',

      policyVersion:
        null,


      // --------------------------
      // Revisión
      // --------------------------

      classificationValid:
        false,

      requiresHumanReview:
        true,


      // --------------------------
      // Auditoría
      // --------------------------

      agentParseError:
        'INVALID_AGENT_JSON',

      agentRawOutput:
        raw,

      agentParsedAt:
        new Date().toISOString(),
    },


    // Conservamos archivo original
    binary:
      sourceItem.binary,
  };
}


// ============================================================
// 7. NORMALIZAR CATEGORÍA
// ============================================================

let expenseCategory =
  String(
    parsed.expenseCategory ??
    'UNCERTAIN'
  )
    .trim()
    .toUpperCase();


if (
  !ALL_CATEGORIES.has(
    expenseCategory
  )
) {

  expenseCategory =
    'UNCERTAIN';
}


const expenseCategoryLabel =
  CATEGORY_LABELS[
    expenseCategory
  ] ??
  'No determinado';


// ============================================================
// 8. NORMALIZAR CONFIANZA
// ============================================================

const expenseConfidence =
  normalizeConfidence(
    parsed.expenseConfidence
  );


const expenseMeetsConfidenceThreshold =
  expenseConfidence >=
  CONFIDENCE_THRESHOLD;


// ============================================================
// 9. EVIDENCIA
// ============================================================

const expenseEvidence =
  normalizeArray(
    parsed.expenseEvidence
  );


const classificationReason =
  normalizeText(
    parsed.classificationReason
  );


// ============================================================
// 10. RESTRICCIONES
// ============================================================

const restrictedItems =
  normalizeArray(
    parsed.restrictedItems
  );


const containsPotentiallyRestrictedItems =
  (
    normalizeBoolean(
      parsed.containsPotentiallyRestrictedItems
    ) === true
  ) ||
  restrictedItems.length > 0;


// ============================================================
// 11. TOOL
// ============================================================

const toolUsed =
  normalizeBoolean(
    parsed.toolUsed
  ) === true;


const policyFound =
  normalizeBoolean(
    parsed.policyFound
  ) === true;


// ============================================================
// 12. POLÍTICA
// ============================================================

const policyAllowed =
  normalizeBoolean(
    parsed.policyAllowed
  );


const policyLimit =
  nullableNumber(
    parsed.policyLimit
  );


const policyRequiresReviewStatus =
  normalizeReviewStatus(
    parsed.policyRequiresReview
  );


const taxReviewStatus =
  normalizeReviewStatus(
    parsed.taxReviewRequired
  );


const policyVersion =
  normalizeText(
    parsed.policyVersion
  );


// ============================================================
// 13. VALIDACIÓN DE CATEGORÍA
// ============================================================

const actionableCategory =
  ACTIONABLE_CATEGORIES.has(
    expenseCategory
  );


const classificationValid =
  actionableCategory &&
  expenseMeetsConfidenceThreshold &&
  !containsPotentiallyRestrictedItems;


// ============================================================
// 14. VALIDAR CONTEXTO DE POLÍTICA
// ============================================================
//
// Para una categoría válida esperamos:
//
// Tool utilizada
// +
// política encontrada
// +
// valor policyAllowed interpretable
//
// policyLimit puede ser null si una política futura
// no utiliza límite económico.
// ============================================================

const policyContextReady =
  actionableCategory &&
  toolUsed &&
  policyFound &&
  policyAllowed !== null;


// ============================================================
// 15. REVISIÓN HUMANA
// ============================================================

const modelRequestedReview =
  normalizeBoolean(
    parsed.requiresHumanReview
  ) === true;


let requiresHumanReview =
  false;


// El modelo pidió revisión
if (modelRequestedReview) {

  requiresHumanReview =
    true;
}


// Categoría fuera de política
if (
  expenseCategory === 'OTHER' ||
  expenseCategory === 'UNCERTAIN'
) {

  requiresHumanReview =
    true;
}


// Confianza insuficiente
if (
  !expenseMeetsConfidenceThreshold
) {

  requiresHumanReview =
    true;
}


// Producto restringido
if (
  containsPotentiallyRestrictedItems
) {

  requiresHumanReview =
    true;
}


// Categoría válida pero no usó Tool
if (
  actionableCategory &&
  !toolUsed
) {

  requiresHumanReview =
    true;
}


// No encontró política
if (
  actionableCategory &&
  !policyFound
) {

  requiresHumanReview =
    true;
}


// Política ausente/incompleta
if (
  actionableCategory &&
  policyFound &&
  policyAllowed === null
) {

  requiresHumanReview =
    true;
}


// Política dice NO
if (
  policyAllowed === false
) {

  requiresHumanReview =
    true;
}


// Política exige revisión
if (
  policyRequiresReviewStatus === 'YES' ||
  policyRequiresReviewStatus === 'CONDITIONAL'
) {

  requiresHumanReview =
    true;
}


// Revisión tributaria
if (
  taxReviewStatus === 'YES' ||
  taxReviewStatus === 'CONDITIONAL'
) {

  requiresHumanReview =
    true;
}


// ============================================================
// 16. ESTADO GENERAL DEL AGENTE
// ============================================================
//
// Esto NO significa todavía "factura aprobada".
//
// Solo significa:
//
// clasificación válida
// +
// Tool correcta
// +
// política encontrada
// +
// política permite el rubro
// +
// no requiere revisión previa.
//
// La comparación:
// total <= policyLimit
//
// se realizará en P07.4.
// ============================================================

const agentDecisionOk =
  classificationValid &&
  policyContextReady &&
  policyAllowed === true &&
  !requiresHumanReview;


// ============================================================
// 17. SALIDA FINAL
// ============================================================

return {

  json: {

    // ========================================================
    // DATOS PREVIOS
    // ========================================================

    ...source,


    // ========================================================
    // AI AGENT
    // ========================================================

    agentResponseParsed:
      true,

    agentDecisionOk,

    policyContextReady,


    // ========================================================
    // CLASIFICACIÓN
    // ========================================================

    expenseCategory,

    expenseCategoryLabel,

    expenseConfidence,

    expenseConfidenceThreshold:
      CONFIDENCE_THRESHOLD,

    expenseMeetsConfidenceThreshold,

    expenseEvidence,

    classificationReason,

    classificationValid,


    // ========================================================
    // RESTRICCIONES
    // ========================================================

    containsPotentiallyRestrictedItems,

    restrictedItems,


    // ========================================================
    // TOOL
    // ========================================================

    toolUsed,

    policyFound,


    // ========================================================
    // POLÍTICA
    // ========================================================

    policyAllowed,

    policyLimit,

    policyRequiresReviewStatus,

    taxReviewStatus,

    policyVersion,


    // ========================================================
    // REVISIÓN
    // ========================================================

    requiresHumanReview,


    // ========================================================
    // AUDITORÍA
    // ========================================================

    agentParsedAt:
      new Date().toISOString(),
  },


  // ========================================================
  // CONSERVAMOS PDF / XML / IMAGEN ORIGINAL
  // ========================================================

  binary:
    sourceItem.binary,
};

// ============================================================
// P07.4 - EVALUAR POLÍTICA DE VIÁTICOS
// Versión 1.1 - Lógica determinista + hospedaje por noche
// ============================================================
//
// La IA ya hizo:
// - clasificación del gasto
// - consulta de política mediante Tool
//
// Este nodo hace únicamente lógica determinista.
//
// REGLA GENERAL:
// monto total <= límite de política
//
// REGLA ESPECIAL LODGING:
// total alojamiento / noches = monto por noche
// monto por noche <= límite de política
//
// Resultado:
// ALLOW  -> cumple política
// REVIEW -> requiere revisión humana
// REJECT -> categoría no permitida por política
// ============================================================


const item = $input.item;
const j = item.json ?? {};


// ============================================================
// CONFIGURACIÓN
// ============================================================

const REQUIRE_POLICY_LIMIT = true;

// Tolerancia monetaria.
const MONEY_TOLERANCE = 0.01;

// Máximo defensivo de noches que aceptamos automáticamente.
const MAX_LODGING_NIGHTS = 365;


// ============================================================
// HELPERS GENERALES
// ============================================================

function toNumber(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  if (typeof value === 'number') {

    return Number.isFinite(value)
      ? value
      : null;
  }

  let text =
    String(value)
      .trim()
      .replace(/\s/g, '')
      .replace(/[^\d,.\-]/g, '');

  if (!text) {
    return null;
  }

  const lastComma =
    text.lastIndexOf(',');

  const lastDot =
    text.lastIndexOf('.');

  // 1.234,56
  if (lastComma > lastDot) {

    text =
      text
        .replace(/\./g, '')
        .replace(',', '.');
  }

  // 1,234.56
  else if (
    lastDot > lastComma &&
    lastComma !== -1
  ) {

    text =
      text.replace(/,/g, '');
  }

  // 40,50
  else if (
    lastComma !== -1 &&
    lastDot === -1
  ) {

    text =
      text.replace(',', '.');
  }

  const number =
    Number(text);

  return Number.isFinite(number)
    ? number
    : null;
}


function normalizeStatus(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return 'UNKNOWN';
  }

  return String(value)
    .trim()
    .toUpperCase();
}


function roundMoney(value) {

  if (
    value === null ||
    value === undefined ||
    !Number.isFinite(value)
  ) {
    return null;
  }

  return Number(
    value.toFixed(2)
  );
}


// ============================================================
// HELPERS DE FECHA
// ============================================================
//
// Devuelve:
// {
//   iso: "2025-03-17",
//   timestamp: ...
// }
//
// Admite:
// DD/MM/YYYY
// DD-MM-YYYY
// YYYY-MM-DD
// ============================================================

function parseDate(value) {

  if (!value) {
    return null;
  }

  const text =
    String(value)
      .trim();

  let year;
  let month;
  let day;

  // DD/MM/YYYY
  // DD-MM-YYYY
  // DD.MM.YYYY
  let match =
    text.match(
      /^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/
    );

  if (match) {

    day =
      Number(match[1]);

    month =
      Number(match[2]);

    year =
      Number(match[3]);

    if (year < 100) {
      year += 2000;
    }
  }

  else {

    // YYYY-MM-DD
    // YYYY/MM/DD
    match =
      text.match(
        /^(\d{4})[\/.\-](\d{1,2})[\/.\-](\d{1,2})$/
      );

    if (!match) {
      return null;
    }

    year =
      Number(match[1]);

    month =
      Number(match[2]);

    day =
      Number(match[3]);
  }

  if (
    !Number.isInteger(year) ||
    !Number.isInteger(month) ||
    !Number.isInteger(day)
  ) {
    return null;
  }

  const date =
    new Date(
      Date.UTC(
        year,
        month - 1,
        day
      )
    );

  // Evita fechas imposibles:
  // 31/02/2025, etc.
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return null;
  }

  const iso =
    [
      String(year).padStart(4, '0'),
      String(month).padStart(2, '0'),
      String(day).padStart(2, '0'),
    ].join('-');

  return {
    iso,
    timestamp:
      date.getTime(),
  };
}


// ============================================================
// EXTRAER FECHA DE INGRESO / CHECK-IN
// ============================================================

function extractCheckIn(text) {

  const patterns = [

    /(?:FECHA\s+(?:DE\s+)?)?INGRESO\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i,

    /(?:FECHA\s+(?:DE\s+)?)?ENTRADA\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i,

    /CHECK\s*[- ]?\s*IN\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i,
  ];

  for (const regex of patterns) {

    const match =
      text.match(regex);

    if (match?.[1]) {

      const parsed =
        parseDate(match[1]);

      if (parsed) {
        return parsed;
      }
    }
  }

  return null;
}


// ============================================================
// EXTRAER FECHA DE SALIDA / CHECK-OUT
// ============================================================

function extractCheckOut(text) {

  const patterns = [

    /(?:FECHA\s+(?:DE\s+)?)?SALIDA\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i,

    /CHECK\s*[- ]?\s*OUT\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i,
  ];

  for (const regex of patterns) {

    const match =
      text.match(regex);

    if (match?.[1]) {

      const parsed =
        parseDate(match[1]);

      if (parsed) {
        return parsed;
      }
    }
  }

  return null;
}


// ============================================================
// RANGO TIPO:
// "DEL 17/03/2025 AL 21/03/2025"
// "DESDE 17/03/2025 HASTA 21/03/2025"
// ============================================================

function extractStayRange(text) {

  const regex =
    /(?:DEL|DESDE)\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})\s*(?:AL|HASTA)\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i;

  const match =
    text.match(regex);

  if (!match) {
    return null;
  }

  const checkIn =
    parseDate(match[1]);

  const checkOut =
    parseDate(match[2]);

  if (
    !checkIn ||
    !checkOut
  ) {
    return null;
  }

  return {
    checkIn,
    checkOut,
  };
}


// ============================================================
// EXTRAER NÚMERO DE NOCHES EXPLÍCITO
// ============================================================
//
// Ejemplos:
//
// "ALOJAMIENTO 04 NOCHES"
// "4 NOCHES"
// "NOCHES: 4"
// "4 DÍAS DE ALOJAMIENTO"
//
// No interpretamos un número aislado como noches.
// ============================================================

function extractExplicitNights(text) {

  const values = [];

  const patterns = [

    /\b(?:ALOJAMIENTO|HOSPEDAJE|ESTAD[IÍ]A)[\s\S]{0,80}?(\d{1,3})\s*NOCHES?\b/gi,

    /\b(\d{1,3})\s*NOCHES?\b/gi,

    /\bNOCHES?\s*[:\-]?\s*(\d{1,3})\b/gi,

    /\b(\d{1,3})\s*D[IÍ]AS?\s+DE\s+(?:ALOJAMIENTO|HOSPEDAJE|ESTAD[IÍ]A)\b/gi,
  ];

  for (const regex of patterns) {

    let match;

    while (
      (match = regex.exec(text)) !== null
    ) {

      const value =
        Number(match[1]);

      if (
        Number.isInteger(value) &&
        value > 0 &&
        value <= MAX_LODGING_NIGHTS
      ) {
        values.push(value);
      }
    }
  }

  return [
    ...new Set(values)
  ];
}


// ============================================================
// DATOS PRINCIPALES
// ============================================================

const total =
  toNumber(j.total);

const policyLimit =
  toNumber(j.policyLimit);

const expenseCategory =
  normalizeStatus(
    j.expenseCategory
  );

const isLodging =
  expenseCategory === 'LODGING';


const policyAllowed =
  j.policyAllowed === true;

const policyExplicitlyRejected =
  j.policyAllowed === false;

const policyFound =
  j.policyFound === true;

const toolUsed =
  j.toolUsed === true;

const agentResponseParsed =
  j.agentResponseParsed === true;

const classificationValid =
  j.classificationValid === true;

const policyContextReady =
  j.policyContextReady === true;

const expenseConfidence =
  toNumber(j.expenseConfidence) ?? 0;

const meetsConfidence =
  j.expenseMeetsConfidenceThreshold === true;

const restricted =
  j.containsPotentiallyRestrictedItems === true;

const requiresHumanReviewFromAgent =
  j.requiresHumanReview === true;

const policyReviewStatus =
  normalizeStatus(
    j.policyRequiresReviewStatus
  );

const taxReviewStatus =
  normalizeStatus(
    j.taxReviewStatus
  );

const rawText =
  String(
    j.rawText ??
    ''
  )
    .replace(/\u00A0/g, ' ')
    .trim();


// ============================================================
// EVALUACIÓN ESPECIAL DE HOSPEDAJE
// ============================================================

let lodgingCheckIn = null;
let lodgingCheckOut = null;

let lodgingExplicitNights = null;
let lodgingDateNights = null;

let lodgingNights = null;
let lodgingNightsSource = null;

let lodgingNightsConflict = false;

let lodgingAmountPerNight = null;

let lodgingEvaluationOk =
  isLodging
    ? false
    : null;


// ============================================================
// SOLO SE EJECUTA PARA LODGING
// ============================================================

if (isLodging) {

  // ----------------------------------------------------------
  // 1. Buscar noches explícitas
  // ----------------------------------------------------------

  const explicitNights =
    extractExplicitNights(
      rawText
    );

  // Si encontramos exactamente una cantidad coherente.
  if (explicitNights.length === 1) {

    lodgingExplicitNights =
      explicitNights[0];
  }

  // Si el propio texto contiene cantidades contradictorias.
  else if (explicitNights.length > 1) {

    lodgingNightsConflict =
      true;
  }


  // ----------------------------------------------------------
  // 2. Buscar check-in / check-out
  // ----------------------------------------------------------

  let checkIn =
    extractCheckIn(
      rawText
    );

  let checkOut =
    extractCheckOut(
      rawText
    );


  // ----------------------------------------------------------
  // 3. Si no encontramos etiquetas, buscar rango
  // ----------------------------------------------------------

  if (
    !checkIn ||
    !checkOut
  ) {

    const range =
      extractStayRange(
        rawText
      );

    if (range) {

      checkIn =
        checkIn ??
        range.checkIn;

      checkOut =
        checkOut ??
        range.checkOut;
    }
  }


  lodgingCheckIn =
    checkIn?.iso ??
    null;

  lodgingCheckOut =
    checkOut?.iso ??
    null;


  // ----------------------------------------------------------
  // 4. Calcular noches por diferencia de fechas
  // ----------------------------------------------------------

  if (
    checkIn &&
    checkOut
  ) {

    const millisecondsPerDay =
      24 * 60 * 60 * 1000;

    const difference =
      (
        checkOut.timestamp -
        checkIn.timestamp
      ) /
      millisecondsPerDay;

    if (
      Number.isInteger(difference) &&
      difference > 0 &&
      difference <= MAX_LODGING_NIGHTS
    ) {

      lodgingDateNights =
        difference;
    }
  }


  // ----------------------------------------------------------
  // 5. Resolver cantidad definitiva de noches
  // ----------------------------------------------------------

  // Tenemos texto + fechas y coinciden.
  if (
    lodgingExplicitNights !== null &&
    lodgingDateNights !== null
  ) {

    if (
      lodgingExplicitNights ===
      lodgingDateNights
    ) {

      lodgingNights =
        lodgingExplicitNights;

      lodgingNightsSource =
        'TEXT_AND_DATES';
    }

    else {

      // Ejemplo:
      // texto dice 4 noches
      // fechas dicen 3 noches
      lodgingNightsConflict =
        true;

      lodgingNights =
        null;

      lodgingNightsSource =
        'CONFLICT';
    }
  }

  // Solo existe cantidad explícita.
  else if (
    lodgingExplicitNights !== null
  ) {

    lodgingNights =
      lodgingExplicitNights;

    lodgingNightsSource =
      'TEXT';
  }

  // Solo tenemos fechas.
  else if (
    lodgingDateNights !== null
  ) {

    lodgingNights =
      lodgingDateNights;

    lodgingNightsSource =
      'DATES';
  }


  // ----------------------------------------------------------
  // 6. Calcular costo por noche
  // ----------------------------------------------------------

  if (
    total !== null &&
    total > 0 &&
    lodgingNights !== null &&
    lodgingNights > 0 &&
    !lodgingNightsConflict
  ) {

    lodgingAmountPerNight =
      roundMoney(
        total /
        lodgingNights
      );

    lodgingEvaluationOk =
      lodgingAmountPerNight !== null;
  }
}


// ============================================================
// BASE DE COMPARACIÓN DE POLÍTICA
// ============================================================
//
// Normal:
// total
//
// Hospedaje:
// total / noches
// ============================================================

let policyComparisonBasis =
  'TOTAL';

let policyComparisonAmount =
  total;


if (isLodging) {

  policyComparisonBasis =
    'PER_NIGHT';

  policyComparisonAmount =
    lodgingEvaluationOk
      ? lodgingAmountPerNight
      : null;
}


// ============================================================
// CÁLCULO DE LÍMITE
// ============================================================

const policyLimitConfigured =
  policyLimit !== null &&
  policyLimit >= 0;


let withinPolicyLimit = null;
let amountOverLimit = null;
let policyUsagePercent = null;


if (
  policyComparisonAmount !== null &&
  policyLimitConfigured
) {

  withinPolicyLimit =
    policyComparisonAmount <=
    policyLimit + MONEY_TOLERANCE;


  amountOverLimit =
    policyComparisonAmount > policyLimit
      ? roundMoney(
          policyComparisonAmount -
          policyLimit
        )
      : 0;


  if (policyLimit > 0) {

    policyUsagePercent =
      Number(
        (
          (
            policyComparisonAmount /
            policyLimit
          ) *
          100
        ).toFixed(2)
      );
  }
}


// ============================================================
// RAZONES
// ============================================================

const reviewReasons = [];
const rejectReasons = [];
const validationWarnings = [];


// ============================================================
// VALIDACIONES TÉCNICAS
// ============================================================

if (!agentResponseParsed) {

  reviewReasons.push(
    'AGENT_RESPONSE_NOT_PARSED'
  );
}


if (!classificationValid) {

  reviewReasons.push(
    'INVALID_EXPENSE_CLASSIFICATION'
  );
}


if (!meetsConfidence) {

  reviewReasons.push(
    'LOW_CLASSIFICATION_CONFIDENCE'
  );
}


if (!toolUsed) {

  reviewReasons.push(
    'POLICY_TOOL_NOT_USED'
  );
}


if (!policyFound) {

  reviewReasons.push(
    'POLICY_NOT_FOUND'
  );
}


if (!policyContextReady) {

  reviewReasons.push(
    'POLICY_CONTEXT_NOT_READY'
  );
}


// ============================================================
// VALIDACIÓN DE TOTAL
// ============================================================

if (
  total === null ||
  total <= 0
) {

  reviewReasons.push(
    'INVALID_TOTAL_FOR_POLICY'
  );
}


// ============================================================
// VALIDACIONES ESPECIALES DE HOSPEDAJE
// ============================================================

if (isLodging) {

  if (lodgingNightsConflict) {

    reviewReasons.push(
      'LODGING_NIGHTS_CONFLICT'
    );
  }


  if (
    lodgingNights === null ||
    lodgingNights <= 0
  ) {

    reviewReasons.push(
      'LODGING_NIGHTS_NOT_DETERMINED'
    );
  }


  if (
    lodgingCheckIn &&
    lodgingCheckOut &&
    lodgingDateNights === null
  ) {

    reviewReasons.push(
      'LODGING_INVALID_STAY_DATES'
    );
  }


  if (
    lodgingNights !== null &&
    lodgingAmountPerNight === null
  ) {

    reviewReasons.push(
      'LODGING_AMOUNT_PER_NIGHT_NOT_CALCULATED'
    );
  }


  // Información útil para auditoría.
  if (
    lodgingNightsSource === 'TEXT'
  ) {

    validationWarnings.push(
      'LODGING_NIGHTS_OBTAINED_FROM_TEXT'
    );
  }


  if (
    lodgingNightsSource === 'DATES'
  ) {

    validationWarnings.push(
      'LODGING_NIGHTS_OBTAINED_FROM_DATES'
    );
  }


  if (
    lodgingNightsSource ===
    'TEXT_AND_DATES'
  ) {

    validationWarnings.push(
      'LODGING_NIGHTS_CONFIRMED_BY_TEXT_AND_DATES'
    );
  }
}


// ============================================================
// POLÍTICA PERMITIDO / NO PERMITIDO
// ============================================================

if (policyExplicitlyRejected) {

  rejectReasons.push(
    'CATEGORY_NOT_ALLOWED_BY_POLICY'
  );
}


if (
  policyFound &&
  j.policyAllowed === null
) {

  reviewReasons.push(
    'POLICY_ALLOWED_VALUE_UNKNOWN'
  );
}


// ============================================================
// LÍMITE DE MONTO
// ============================================================

if (
  REQUIRE_POLICY_LIMIT &&
  !policyLimitConfigured
) {

  reviewReasons.push(
    'POLICY_LIMIT_NOT_CONFIGURED'
  );
}


if (
  withinPolicyLimit === false
) {

  // Superar el límite genera revisión humana,
  // no rechazo automático.
  //
  // Para LODGING:
  // compara importe por noche.
  //
  // Para otras categorías:
  // compara total.
  reviewReasons.push(
    'AMOUNT_EXCEEDS_POLICY_LIMIT'
  );
}


// ============================================================
// PRODUCTOS RESTRINGIDOS
// ============================================================

if (restricted) {

  reviewReasons.push(
    'POTENTIALLY_RESTRICTED_ITEMS'
  );
}


// ============================================================
// REVISIÓN DEFINIDA EN POLÍTICA
// ============================================================

if (
  policyReviewStatus === 'YES' ||
  policyReviewStatus === 'CONDITIONAL'
) {

  reviewReasons.push(
    'POLICY_REQUIRES_REVIEW'
  );
}


// ============================================================
// REVISIÓN TRIBUTARIA
// ============================================================

if (
  taxReviewStatus === 'YES' ||
  taxReviewStatus === 'CONDITIONAL'
) {

  reviewReasons.push(
    'TAX_REVIEW_REQUIRED'
  );
}


// ============================================================
// REVISIÓN PEDIDA POR EL AGENTE
// ============================================================

if (requiresHumanReviewFromAgent) {

  reviewReasons.push(
    'AGENT_REQUESTED_HUMAN_REVIEW'
  );
}


// ============================================================
// ELIMINAR RAZONES REPETIDAS
// ============================================================

const uniqueReviewReasons =
  [...new Set(reviewReasons)];

const uniqueRejectReasons =
  [...new Set(rejectReasons)];

const uniqueValidationWarnings =
  [...new Set(validationWarnings)];


// ============================================================
// DECISIÓN FINAL
// ============================================================

let policyDecision =
  'REVIEW';


// REJECT tiene prioridad máxima.
if (
  uniqueRejectReasons.length > 0
) {

  policyDecision =
    'REJECT';
}


// Si existen razones de revisión.
else if (
  uniqueReviewReasons.length > 0
) {

  policyDecision =
    'REVIEW';
}


// Todo correcto.
else {

  policyDecision =
    'ALLOW';
}


// ============================================================
// FLAGS
// ============================================================

const policyAutoApproved =
  policyDecision === 'ALLOW';

const policyNeedsHumanApproval =
  policyDecision === 'REVIEW';

const policyRejected =
  policyDecision === 'REJECT';


// ============================================================
// ESTADO DE EVALUACIÓN
// ============================================================
//
// Para hospedaje también necesitamos haber calculado
// correctamente las noches.
// ============================================================

const policyEvaluationOk =
  agentResponseParsed &&
  total !== null &&
  policyFound &&
  (
    !isLodging ||
    lodgingEvaluationOk === true
  );


// ============================================================
// LABEL
// ============================================================

const POLICY_DECISION_LABELS = {

  ALLOW:
    'Cumple política',

  REVIEW:
    'Requiere revisión humana',

  REJECT:
    'No permitido por política',
};


const policyDecisionLabel =
  POLICY_DECISION_LABELS[
    policyDecision
  ];


// ============================================================
// SALIDA
// ============================================================

return {

  json: {

    // --------------------------------------------------------
    // Conservamos todo P01-P07.3
    // --------------------------------------------------------

    ...j,


    // --------------------------------------------------------
    // Base utilizada para comparar política
    // --------------------------------------------------------

    policyComparisonBasis,

    policyComparisonAmount,


    // --------------------------------------------------------
    // Hospedaje
    // --------------------------------------------------------

    isLodging,

