    lodgingDateNights,

    lodgingNights,

    lodgingNightsSource,

    lodgingNightsConflict,

    lodgingAmountPerNight,

    lodgingEvaluationOk,


    // --------------------------------------------------------
    // Resultado monetario
    // --------------------------------------------------------

    policyLimitConfigured,

    withinPolicyLimit,

    amountOverLimit,

    policyUsagePercent,


    // --------------------------------------------------------
    // P07.4
    // --------------------------------------------------------

    policyEvaluationOk,

    policyDecision,

    policyDecisionLabel,


    // --------------------------------------------------------
    // Flags para IF / Switch
    // --------------------------------------------------------

    policyAutoApproved,

    policyNeedsHumanApproval,

    policyRejected,


    // --------------------------------------------------------
    // Explicabilidad
    // --------------------------------------------------------

    policyReviewReasons:
      uniqueReviewReasons,

    policyRejectReasons:
      uniqueRejectReasons,

    policyValidationWarnings:
      uniqueValidationWarnings,


    // --------------------------------------------------------
    // Auditoría
    // --------------------------------------------------------

    policyEvaluatedAt:
      new Date().toISOString(),
  },


  // Conservamos JPG / PDF / XML
  binary:
