// ============================================================
// P08.1 - PREPARAR REGISTRO DE FACTURA
// ============================================================

const item = $input.item;
const j = item.json ?? {};


// ============================================================
// HELPERS
// ============================================================

function text(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return '';
  }

  return String(value).trim();
}


function numberOrBlank(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return '';
  }

  const number = Number(value);

  return Number.isFinite(number)
    ? number
    : '';
}


function booleanText(value) {
  if (value === true) {
    return 'SI';
  }

  if (value === false) {
    return 'NO';
  }

  return '';
}


function arrayText(value) {
  if (!Array.isArray(value)) {
    return '';
  }

  return value
    .map(v => String(v ?? '').trim())
    .filter(Boolean)
    .join(' | ');
}


