  // Decisión
  // ----------------------------------------------------------

  policyDecision:
    text(j.policyDecision),

  policyDecisionLabel:
    text(j.policyDecisionLabel),

  policyReviewReasons:
    arrayText(j.policyReviewReasons),

  policyRejectReasons:
    arrayText(j.policyRejectReasons),

  requiresHumanReview:
    booleanText(j.requiresHumanReview),

  status,
};


// ============================================================
// SALIDA
// ============================================================

return {
  json: record,

  // Conservamos archivo por si la siguiente rama lo necesita
  binary: item.binary
};

// ============================================================
// P08.2 - RESTAURAR CONTEXTO DESPUÉS DEL REGISTRO
// ============================================================
//
// Google Sheets puede devolver solamente la fila registrada.
// Recuperamos la decisión completa desde P07.4.
//
// Para esta versión trabajamos con 1 factura por ejecución,
// por eso usamos .first().
// ============================================================

const policyItem =
  $('Evaluar política (P18)').first();

if (!policyItem) {
  throw new Error(
    'No se encontró información en "Evaluar política (P07.4)"'
  );
}

const policyData =
  policyItem.json ?? {};

const registerResult =
  $json ?? {};


// ============================================================
// SALIDA
// ============================================================

return {
  json: {
    // Toda la factura + colaborador + IA + política
    ...policyData,

    // Auditoría P08
    invoiceRegistered: true,

    registeredRowNumber:
      registerResult.row_number ??
      registerResult.rowNumber ??
      null,

    registeredAt:
      new Date().toISOString(),
  },

  // Conservamos archivo original
  binary:
    policyItem.binary,
};

// ============================================================
// P09.9 - PREPARAR RESULTADO FINAL
// ============================================================

const item = $input.item;
const j = item.json ?? {};


// ============================================================
// 1. DETERMINAR TIPO DE APROBACIÓN
// ============================================================

const humanApproved =
  j.humanApproved === true ||
  j.humanApprovalStatus === 'APPROVED';

const autoApproved =
  j.policyDecision === 'ALLOW' &&
  !humanApproved;


// ============================================================
// 2. ESTADO FINAL
// ============================================================

let finalStatus = 'PROCESSED';
let finalStatusLabel = 'Procesada';
let approvalType = 'NONE';

if (autoApproved) {

  finalStatus =
    'AUTO_APPROVED';

  finalStatusLabel =
    'Aprobada automáticamente';

  approvalType =
    'AUTOMATIC';
}

if (humanApproved) {

  finalStatus =
    'HUMAN_APPROVED';

  finalStatusLabel =
    'Aprobada manualmente';

  approvalType =
    'HUMAN';
}


// ============================================================
// 3. DESTINATARIO
// ============================================================

const recipientEmail =
  String(
    j.senderEmail ||
    j.collaboratorEmail ||
    ''
  )
  .trim()
  .toLowerCase();


// ============================================================
// 4. VALIDAR EMAIL
// ============================================================

const recipientEmailValid =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    .test(recipientEmail);


// ============================================================
// 5. ASUNTO
// ============================================================

const documentNumber =
  j.documentNumber ||
  'SIN-NUMERO';

const finalEmailSubject =
  `Rendición ${documentNumber} - ${finalStatusLabel}`;


// ============================================================
// 6. SALIDA
// ============================================================

return {
  json: {

    ...j,

    approvalType,

    finalStatus,
    finalStatusLabel,

    recipientEmail,
    recipientEmailValid,

    finalEmailSubject,

    finalApproved:
      autoApproved ||
      humanApproved,

    finalProcessedAt:
      new Date().toISOString(),
  },

  binary:
    item.binary,
};

// ============================================================
// P09.11 - PREPARAR RECHAZO FINAL
// ============================================================
//
// Puede recibir:
// A) REJECT directo de la política
// B) REVIEW rechazado por una persona
//
// Genera un formato único para la notificación y registro.
// ============================================================

const item = $input.item;
const j = item.json ?? {};


// ============================================================
// 1. IDENTIFICAR ORIGEN DEL RECHAZO
// ============================================================

const humanRejected =
  j.humanApproved === false ||
  j.humanApprovalStatus === 'REJECTED';

const policyRejected =
  j.policyDecision === 'REJECT';


// ============================================================
// 2. DETERMINAR TIPO Y MENSAJE
// ============================================================

let rejectionType = 'POLICY';
let finalStatusLabel = 'No permitida por la política';

if (humanRejected) {
  rejectionType = 'HUMAN';
  finalStatusLabel = 'Rechazada por el aprobador';
} else if (policyRejected) {
  rejectionType = 'POLICY';
  finalStatusLabel = 'No permitida por la política';
}


// ============================================================
// 3. DESTINATARIO
// ============================================================

const recipientEmail =
  String(
    j.senderEmail ||
    j.collaboratorEmail ||
    ''
  )
    .trim()
    .toLowerCase();

const recipientEmailValid =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    .test(recipientEmail);


// ============================================================
// 4. MOTIVOS
// ============================================================

const policyRejectReasons =
  Array.isArray(j.policyRejectReasons)
    ? j.policyRejectReasons
    : [];

const policyReviewReasons =
  Array.isArray(j.policyReviewReasons)
    ? j.policyReviewReasons
    : [];


// ============================================================
// 5. ESTADO FINAL
// ============================================================

const finalStatus = 'REJECTED';
const finalApproved = false;

const finalEmailSubject =
  `Rendición ${j.documentNumber || 'SIN-NUMERO'} - ${finalStatusLabel}`;

const finalProcessedAt =
  new Date().toISOString();


// ============================================================
// 6. SALIDA
// ============================================================

return {
  json: {
    ...j,

    finalApproved,
    finalStatus,
    finalStatusLabel,

    rejectionType,

    recipientEmail,
    recipientEmailValid,

    policyRejectReasons,
    policyReviewReasons,

    finalEmailSubject,
    finalProcessedAt,
  },

  binary: item.binary,
};

