parameters.jsCode:
// ============================================================
// P09.2 - NORMALIZAR APROBACIÓN HUMANA
// ============================================================
//
// Objetivos:
// 1. Interpretar la respuesta del Gmail HITL.
// 2. Recuperar todos los datos originales de la factura.
// 3. Conservar el archivo binario.
// 4. Crear un booleano estable: humanApproved.
//
// V1:
// Trabajamos con una factura por ejecución.
// ============================================================


// ============================================================
// 1. RECUPERAR CONTEXTO ORIGINAL
// ============================================================

const sourceItem =
  $('Restaurar contexto (P21)').first();

if (!sourceItem) {
  throw new Error(
    'No se encontró el contexto original en "Restaurar contexto (P08.2)"'
  );
}

const source =
  sourceItem.json ?? {};


// ============================================================
// 2. RESPUESTA DEL NODO HITL
// ============================================================

const response =
  $json ?? {};


// ============================================================
// 3. EXTRAER VALOR DE APROBACIÓN
// ============================================================
//
// Tu salida actual:
//
// {
//   "datos": {
//     "aprobado": true,
//     "respondióEn": "..."
//   }
// }
//
// También dejamos compatibilidad con nombres ingleses,
// por si una actualización de n8n cambia la estructura.
// ============================================================

const rawApproved =
  response.datos?.aprobado ??
  response.data?.approved ??
  response.aprobado ??
  response.approved ??
  null;


// ============================================================
// 4. NORMALIZAR BOOLEANO
// ============================================================

function normalizeBoolean(value) {

  if (value === true) {
    return true;
  }

  if (value === false) {
    return false;
  }

  if (value === null || value === undefined) {
    return null;
  }

  const normalized =
    String(value)
      .trim()
      .toLowerCase();

  if (
    [
      'true',
      'verdadero',
      'yes',
      'si',
      'sí',
      'approved',
      'approve',
      'aprobado',
      'aprobar'
    ].includes(normalized)
  ) {
    return true;
  }

  if (
    [
      'false',
      'falso',
      'no',
      'rejected',
      'reject',
      'disapproved',
      'declined',
      'rechazado',
      'rechazar'
    ].includes(normalized)
  ) {
    return false;
  }

  return null;
}


const humanApproved =
  normalizeBoolean(rawApproved);


// ============================================================
// 5. FECHA/HORA DE RESPUESTA
// ============================================================

const humanApprovalRespondedAt =
  response.datos?.['respondióEn'] ??
  response.datos?.respondioEn ??
  response.data?.respondedAt ??
  response.respondedAt ??
  new Date().toISOString();


// ============================================================
// 6. ESTADO NORMALIZADO
// ============================================================

const humanApprovalResolved =
  humanApproved !== null;

let humanApprovalStatus =
  'UNKNOWN';

if (humanApproved === true) {
  humanApprovalStatus =
    'APPROVED';
}

if (humanApproved === false) {
  humanApprovalStatus =
    'REJECTED';
}


// ============================================================
// 7. RESULTADO FINAL
// ============================================================

return {
  json: {

    // Recuperamos todos los datos anteriores
    ...source,

    // Auditoría HITL
    approvalType:
      'HUMAN',

    humanApprovalResolved,

    humanApproved,

    humanApprovalStatus,

    humanApprovalRespondedAt,

    // Guardamos la respuesta original para auditoría
    humanApprovalRawResponse:
      response,

  },

  // Recuperamos el comprobante original
  binary:
    sourceItem.binary,
};

