parameters.jsCode:
// ============================================================
// P10.0 - PREPARAR ACTUALIZACIÓN DE ESTADO APROBADO
// ============================================================
//
// Recuperamos el estado final desde P09.9 y construimos
// exactamente las columnas que Google Sheets debe actualizar.
// ============================================================

const sourceItem =
  $('Preparar resultado final (P23.1)').first();

if (!sourceItem) {
  throw new Error(
    'No se encontró "Preparar resultado final (P09.9)"'
  );
}

const j =
  sourceItem.json ?? {};


// ============================================================
// VALIDACIONES BÁSICAS
// ============================================================

if (!j.duplicateKey) {
  throw new Error(
    'No existe duplicateKey para actualizar RegistroFacturas'
  );
}

if (!j.finalStatus) {
  throw new Error(
    'No existe finalStatus para actualizar RegistroFacturas'
  );
}


// ============================================================
// SALIDA
// ============================================================
//
// IMPORTANTE:
// Los nombres deben coincidir exactamente con las columnas
// de Google Sheets.
// ============================================================

return {
  json: {

    duplicateKey:
      j.duplicateKey,

    status:
      j.finalStatus,

    finalStatus:
      j.finalStatus,

    finalStatusLabel:
      j.finalStatusLabel ?? '',

    finalApproved:
      j.finalApproved ?? false,

    approvalType:
      j.approvalType ?? '',

    humanApprovalStatus:
      j.humanApprovalStatus ?? '',

    humanApprovalRespondedAt:
      j.humanApprovalRespondedAt ?? '',

    finalProcessedAt:
      j.finalProcessedAt ??
      new Date().toISOString(),
  }
};

// ============================================================
// P10.R0 - PREPARAR ACTUALIZACIÓN DE ESTADO RECHAZADO
// ============================================================

const sourceItem =
  $('Preparar rechazo final (P23.3)').first();

if (!sourceItem) {
  throw new Error(
    'No se encontró "Preparar rechazo final (P09.11)"'
  );
}

const j =
  sourceItem.json ?? {};


// ============================================================
// VALIDACIONES
// ============================================================

if (!j.duplicateKey) {
  throw new Error(
    'No existe duplicateKey para actualizar RegistroFacturas'
  );
}

if (j.finalStatus !== 'REJECTED') {
  throw new Error(
    `Estado inesperado para rama de rechazo: ${j.finalStatus}`
  );
}


// ============================================================
// SALIDA PARA MAP AUTOMATICALLY
// ============================================================

return {
  json: {

    duplicateKey:
      j.duplicateKey,

    status:
      'REJECTED',

    finalStatus:
      'REJECTED',

    finalStatusLabel:
      j.finalStatusLabel ?? 'No aprobada',

    finalApproved:
      false,

    approvalType:
      j.rejectionType === 'HUMAN'
        ? 'HUMAN'
        : 'POLICY',

    rejectionType:
      j.rejectionType ?? 'POLICY',

    humanApprovalStatus:
      j.humanApprovalStatus ?? '',

    humanApprovalRespondedAt:
      j.humanApprovalRespondedAt ?? '',

    finalProcessedAt:
      j.finalProcessedAt ??
      new Date().toISOString(),
  }
};
